css:
        thead {

            align-items: center;
        }

        body:last-child .print-format td img {
                position: relative;
                bottom:0;
                top:0;
            }
        thead img {
            max-width: 150px;
        }

        h2{
        margin-bottom:0px!important;    
        }
        .title h3{
            margin-bottom:-13px;
            font-size: 18px;
            font-weight: 600;
            letter-spacing: -1.1px;
            margin-left:28px;

        }

        img {
            position: absolute;
            left: 0;
        }
       #data{
           background:darkgrey;
           font-size:15px;
           padding:5px 70px !important;
           border-radius:5px;
           font-weight:bold;

       }
       #SN{
        width:30%;
        background:black;
        color:white;
       }

        #bold{
            font-weight:bold;
        }
        .info {
            display: flex;
            margin-top:20px;
            padding:5px 10px !important;
            border: 2px solid black;
            border-radius: 15px;
            width : 100%;
        }

        .left-section {
            width : 60%;
            margin-left: 10px;
        }

          .right-section {
            width : 40%;
        }
        .right-section  span{
         margin-left:5px;

        }
        .info p {
            font-weight: bold;
        }

        .info span {
            font-weight: lighter;
        }

        .info b {
            position: absolute;
            bottom: 8px;
            right:10px;
            color: grey;
        }

        table {
            width: 100%;
            border-collapse: collapse;
            margin-top: 10px;
        }
        .print-format td, .print-format th{
            padding:5px!important;
            color:black;
            text-align:center;
        }
        th,td {
            border: 1px solid #000;
            padding: 5px;
        }

        th {

            text-align: left;
            color:black;
         font-weight:600;
        }

        .foot {
            display: flex;
            justify-content: space-between;
        }

        .signatures {
            display: flex;
            justify-content: space-between;
            padding-top: 12px;
            width: 100%;
        }

        .signatures div {
            text-align: center;
            border-bottom: 1px solid #000;
            width: 18%;
        }

        .total {
            text-align: center;
            padding: 10px 2px;
            width:100%;
            border-top:0px;
        }

        .total p {
            margin: 0;
        }

        .total p:first-child {
            font-weight: bold;
            background: #c0c0c0;
            font-size:20px;

        }
        @media print {
        table {
            width: 100%;
            border-collapse: collapse;
        }


        thead {
            display: table-header-group !important;

        }

        tfoot {
            display: table-footer-group !important;

        }

        tbody {
            display: table-row-group !important;
        }

        table td div {
            page-break-inside: auto !important;
        }
        }
.text-start{
    text-align: left !important;
}

.b-none{
    border: none !important;
}
.logo{
    text-align:center;
}        
.logo img{
    margin-top: 0px;
}
.content{
    width: 65%;
}
.highlight{
    text-align:center;
    background-color: #c0c0c0;
    border-radius: 10px;
    color:black;
    padding: 5px 50px;
    margin-bottom:5px;
}

.main-tfoot tr td:last-child {
    display: none;
}
.main-tfoot{
        position:absolute;
        bottom:0;
        left:0;
        right:0;
        width:100%;
}
